void    out_exec_start( Out out , UInt32 t_offset , UInt32 t_on , UInt32 t_off , UInt16 pulse )
{
    out->time  = 0                        ;
    out->pulse = 0                        ;
    
	out->frame.t_offset = t_offset        ;
	out->frame.t_on     = t_on            ;
	out->frame.t_off    = t_off           ;
	out->frame.pulse    = pulse           ;
                         
    out->state = (Out_State)out_state_offset  ;    
}

